/*Table structure for table `tbl_biking_session` */

DROP TABLE IF EXISTS `tbl_biking_session`;

CREATE TABLE `tbl_biking_session` (
  `sess_id` varchar(128) NOT NULL,
  `sess_time_begin` datetime NOT NULL,
  `sess_time_last` datetime NOT NULL,
  `sess_hostname` varchar(50) NOT NULL,
  `sess_browser` varchar(50) NOT NULL,
  `sess_pub_addr` varchar(60) NOT NULL,
  `sess_emp_fid` int(11) NOT NULL,
  `sess_mb_uid` varchar(30) NOT NULL,
  `sess_running` int(11) NOT NULL,
  `sess_betting_domain` varchar(50) NOT NULL,
  `sess_betting_user` varchar(50) NOT NULL,
  `sess_betting_real` int(11) NOT NULL,
  `sess_money_begin` bigint(20) NOT NULL,
  `sess_money_current` bigint(20) NOT NULL,
  `sess_virtual_begin` bigint(20) NOT NULL,
  `sess_virtual_current` bigint(20) NOT NULL,
  `sess_app_title` varchar(50) NOT NULL,
  `sess_app_version` varchar(50) NOT NULL,
  `sess_room_0_level` int(11) NOT NULL,
  `sess_room_0_earn` int(11) NOT NULL,
  `sess_room_0_win` int(11) NOT NULL,
  `sess_room_0_loss` int(11) NOT NULL,
  `sess_room_1_level` int(11) NOT NULL,
  `sess_room_1_earn` int(11) NOT NULL,
  `sess_room_1_win` int(11) NOT NULL,
  `sess_room_1_loss` int(11) NOT NULL,
  `sess_room_2_level` int(11) NOT NULL,
  `sess_room_2_earn` int(11) NOT NULL,
  `sess_room_2_win` int(11) NOT NULL,
  `sess_room_2_loss` int(11) NOT NULL,
  `sess_room_3_level` int(11) NOT NULL,
  `sess_room_3_earn` int(11) NOT NULL,
  `sess_room_3_win` int(11) NOT NULL,
  `sess_room_3_loss` int(11) NOT NULL,
  `sess_memo_1` varchar(50) NOT NULL,
  `sess_memo_2` varchar(50) NOT NULL,
  `sess_memo_3` varchar(50) NOT NULL,
  `sess_memo_4` varchar(50) NOT NULL,
  `sess_memo_5` varchar(50) NOT NULL,
  `sess_prop_1` int(11) NOT NULL,
  `sess_prop_2` int(11) NOT NULL,
  `sess_prop_3` int(11) NOT NULL,
  `sess_prop_4` int(11) NOT NULL,
  `sess_prop_5` int(11) NOT NULL,
  PRIMARY KEY (`sess_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

