/*Table structure for table `tbl_copycat_bet` */

DROP TABLE IF EXISTS `tbl_copycat_bet`;

CREATE TABLE `tbl_copycat_bet` (
  `bet_fid` int(11) NOT NULL AUTO_INCREMENT,
  `bet_date` datetime NOT NULL,
  `bet_mb_uid` varchar(30) NOT NULL,
  `bet_domain` varchar(30) NOT NULL,
  `bet_guser` varchar(50) NOT NULL,
  `bet_gpass` varchar(50) NOT NULL,
  `bet_room1_wins` int(11) NOT NULL,
  `bet_room2_wins` int(11) NOT NULL,
  `bet_room3_wins` int(11) NOT NULL,
  `bet_room4_wins` int(11) NOT NULL,
  `bet_room1_loss` int(11) NOT NULL,
  `bet_room2_loss` int(11) NOT NULL,
  `bet_room3_loss` int(11) NOT NULL,
  `bet_room4_loss` int(11) NOT NULL,
  `bet_room1_earn` int(11) NOT NULL,
  `bet_room2_earn` int(11) NOT NULL,
  `bet_room3_earn` int(11) NOT NULL,
  `bet_room4_earn` int(11) NOT NULL,
  `bet_memo_1` varchar(50) NOT NULL,
  `bet_memo_2` varchar(50) NOT NULL,
  `bet_prop_1` int(11) NOT NULL,
  `bet_prop_2` int(11) NOT NULL,
  PRIMARY KEY (`bet_fid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

/*Data for the table `tbl_copycat_bet` */

/*Table structure for table `tbl_copycat_member` */

DROP TABLE IF EXISTS `tbl_copycat_member`;

