  `mb_fid` int(11) NOT NULL AUTO_INCREMENT,
  `mb_emp_fid` int(11) NOT NULL,
  `mb_uid` varchar(50) NOT NULL,
  `mb_pwd` varchar(50) NOT NULL,
  `mb_nickname` varchar(50) NOT NULL,
  `mb_phone` varchar(30) NOT NULL,
  `mb_level` int(11) NOT NULL,
  `mb_vip` int(11) NOT NULL,
  `mb_domain` varchar(30) NOT NULL,
  `mb_time_join` datetime NOT NULL,
  `mb_time_last` datetime NOT NULL,
  `mb_time_limit` datetime NOT NULL,
  `mb_last_ip` varchar(60) NOT NULL,
  `mb_state_active` int(11) NOT NULL,
  `mb_state_delete` int(11) NOT NULL,
  `mb_memo_1` varchar(512) NOT NULL,
  `mb_memo_2` text NOT NULL,
  `mb_prop_1` int(11) NOT NULL,
  `mb_prop_2` int(11) NOT NULL,
  PRIMARY KEY (`mb_fid`)
) ENGINE=InnoDB AUTO_INCREMENT=186 DEFAULT CHARSET=utf8mb4;

