/*Table structure for table `tbl_copycat_session` */

DROP TABLE IF EXISTS `tbl_copycat_session`;

CREATE TABLE `tbl_copycat_session` (
  `sess_id` varchar(128) NOT NULL,
  `sess_time_begin` datetime NOT NULL,
  `sess_time_last` datetime NOT NULL,
