  `bet_room4_wins` int(11) NOT NULL,
  `bet_room1_loss` int(11) NOT NULL,
  `bet_room2_loss` int(11) NOT NULL,
  `bet_room3_loss` int(11) NOT NULL,
  `bet_room4_loss` int(11) NOT NULL,
  `bet_room1_earn` int(11) NOT NULL,
  `bet_room2_earn` int(11) NOT NULL,
  `bet_room3_earn` int(11) NOT NULL,
  `bet_room4_earn` int(11) NOT NULL,
  `bet_memo_1` varchar(50) NOT NULL,
